    proof fn lemma_addr_not_free(&self, idx: int, fa: int)
        requires
            fa == frame_addr_of(idx),
            spec_page_size() > 0,
            !self.bitmap@.is_covered(idx) || self.bitmap@.set_bits.contains(idx),
