                let i = choose|i: int|
                    old_inner.bitmap@.is_covered(i)
                    && !old_inner.bitmap@.set_bits.contains(i)
                    && addr == frame_addr_of(i);
                assert(self.bitmap@.is_covered(i));
                if range.contains(i) {
                    assert(frames.contains(addr));
                    assert(false);
                }
                assert(!self.bitmap@.set_bits.contains(i));
            }
        }

