    proof fn lemma_frame_quotients_bounded(start: int, size: int, ps: int)
        requires
            ps >= 2,
            start >= 0,
            size >= 0,
            start % ps == 0,
            size % ps == 0,
            start + size <= usize::MAX as int,
        ensures
            start / ps + size / ps <= usize::MAX as int,
    {
