        assert(start + size == ((sfn) + (nf)) * (ps as int)) by (nonlinear_arith)
            requires
                start == (sfn) * ps,
                size == (nf) * ps,
        {}
        assert(((sfn) + (nf)) * (ps as int) == (sfn + nf) * (ps as int)) by (nonlinear_arith)
