    /// Prove set_int_range grows by one element.
    proof fn lemma_range_insert_step(sfn: int, idx: int)
        requires
            sfn <= idx,
        ensures
            vstd::set_lib::set_int_range(sfn, (idx + 1) as int) =~=
                vstd::set_lib::set_int_range(sfn, idx as int).insert(idx as int),
    {
        // vstd's lemma_int_range already proves:
        //   set_int_range(lo, hi - 1).insert(hi - 1) =~= set_int_range(lo, hi)
        // With hi = idx + 1, this gives exactly our goal.
        vstd::set_lib::lemma_int_range(sfn, (idx + 1) as int);
    }

    /// Prove that an index that is not free (uncovered or already set) makes the
    /// range subset_of(free_frames) property false. Used by both the coverage-check
    /// and the test-loop error paths in alloc_range.
    proof fn lemma_alloc_range_conflict(
        &self,
        old_inner: &Inner,
        sfn: int,
        efn: int,
        index: int,
    )
        requires
            self.bitmap@ =~= old_inner.bitmap@,
            self.internal_inv(),
            sfn == old_inner.bitmap@.set_bits.filter(|i: int| old_inner.bitmap@.is_covered(i)).len() - old_inner.bitmap@.set_bits.filter(|i: int| old_inner.bitmap@.is_covered(i)).len() + sfn,
            sfn <= index && index < efn,
            // index is NOT free (either uncovered or already set)
            !old_inner@.free_frames.contains(frame_addr_of(index)),
            spec_page_size() > 0,
        ensures ({
            let pc_fns = vstd::set_lib::set_int_range(sfn, efn);
            let pc_frames = pc_fns.map(|i: int| i * spec_page_size());
            &&& !pc_frames.subset_of(old_inner@.free_frames)
            &&& self.inv()
        }),
    {
        let ps = spec_page_size();
        let pc_fns = vstd::set_lib::set_int_range(sfn, efn);
        let pc_frames = pc_fns.map(|i: int| i * ps);
        let fa = frame_addr_of(index);
        assert(pc_fns.contains(index));
        assert(pc_frames.contains(fa));
        assert(!old_inner@.free_frames.contains(fa));
        assert(!pc_frames.subset_of(old_inner@.free_frames));
        self.lemma_inv_implies_wf();
    }
}

} // verus!

